import type { FC } from 'react';
import { motion } from 'framer-motion';
import { useState } from 'react';
import { ChevronDown } from 'lucide-react';
import portfolioData from '../data/portfolio.json';

const Experience: FC = () => {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);

  const toggleAccordion = (index: number) => {
    setExpandedIndex(expandedIndex === index ? null : index);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="pt-24"
    >
      <section className="section-container pt-0 pb-12 md:py-1">
        <div className="text-center mb-8 md:mb-12">
          <h1 className="text-2xl md:text-3xl font-display font-medium mb-6 text-accent">Experience</h1>
          <p className="text-muted-foreground max-w-2xl mx-auto text-xl font-light leading-relaxed">
            running smoothly since 2021
          </p>
        </div>

        <div className="space-y-4">
          {portfolioData.experience.map((exp, index) => (
            <motion.div
              key={exp.company}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: index * 0.1 }}
              className="glass-panel"
            >
              <button
                onClick={() => toggleAccordion(index)}
                className="w-full p-6 flex items-center justify-between text-left rounded-xl"
                aria-expanded={expandedIndex === index}
              >
                <div className="flex-1 flex items-center gap-4">
                  <div className="w-16 h-16 shrink-0 flex items-center justify-center rounded-lg bg-background/50 border border-border overflow-hidden">
                    <img
                      src={exp.company_logo}
                      alt={`${exp.company} logo`}
                      width={64}
                      height={64}
                      loading="lazy"
                      decoding="async"
                      className="w-full h-full object-contain p-1.5"
                    />
                  </div>
                  <div>
                    <h2 className="text-xl font-semibold text-foreground mb-2">{exp.title}</h2>
                    <div className="flex flex-wrap gap-4 text-muted-foreground">
                      <span>{exp.company}</span>
                      <span>•</span>
                      <span>{exp.period}</span>
                    </div>
                  </div>
                </div>
                <ChevronDown
                  className={`w-6 h-6 text-muted-foreground transition-transform duration-300 ${
                    expandedIndex === index ? 'transform rotate-180' : ''
                  }`}
                />
              </button>

              <motion.div
                initial={false}
                animate={{ height: expandedIndex === index ? 'auto' : 0, opacity: expandedIndex === index ? 1 : 0 }}
                transition={{ duration: 0.3, ease: "easeInOut" }}
                className="overflow-hidden"
              >
                <div className="px-6 pb-6">
                  <div className="min-h-[1px]">
                    {exp.description && <p className="text-foreground/80 mb-6">{exp.description}</p>}
                    <ul className="space-y-3 text-foreground/80">
                      {exp.role_responsibilities.map((responsibility, idx) => (
                        <motion.li
                          key={idx}
                          initial={{ opacity: 0, x: -20 }}
                          animate={{ opacity: 1, x: 0 }}
                          transition={{ delay: idx * 0.1 }}
                          className="flex items-start gap-3"
                        >
                          <span className="text-accent text-xl" aria-hidden="true">•</span>
                          <p>{responsibility}</p>
                        </motion.li>
                      ))}
                    </ul>

                    {exp.clients && exp.clients.length > 0 && (
                      <div className="mt-8">
                        <h4 className="text-lg font-semibold text-foreground mb-4">Key Clients</h4>
                        <div className="flex flex-wrap gap-4">
                          {exp.clients.map((client, idx) => (
                            <motion.div
                              key={idx}
                              initial={{ opacity: 0, y: 10 }}
                              animate={{ opacity: 1, y: 0 }}
                              transition={{ delay: 0.2 + (idx * 0.1) }}
                              className="bg-secondary/40 px-4 py-2 rounded-full text-sm text-foreground/80 border border-border"
                            >
                              {client}
                            </motion.div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </motion.div>
            </motion.div>
          ))}
        </div>
      </section>
    </motion.div>
  );
};

export default Experience;
